const calldata = "";
const argsPart = calldata.slice(10);
const offset = parseInt(argsPart.slice(0, 64), 16) * 2;
console.log("Offset:", offset/2);
const length = parseInt(argsPart.slice(offset, offset + 64), 16) * 2;
console.log("Length:", length/2);
const data = argsPart.slice(offset + 64, offset + 64 + length);
console.log("Data length:", data.length/2);
console.log("Data:", data);
